insert into public.form_templates (id,code,title,purpose,document_id,schema,status,rev) values
('800e5909-7f22-5df1-8bf9-84c8a84edad3'::uuid,'CAP-F01','DRRM skills inventory','Chapter 9 CAP-F01 (SOP 9-01). Counts by skill, office and barangay; blank means "not reported".','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'{"fields": [{"key": "unit", "label": "Office (CDRRMO division, City office or barangay)", "type": "text", "required": true}, {"key": "skill", "label": "Skill", "type": "select", "required": true, "options": ["ICS", "Basic life support / first aid", "Water search and rescue", "Collapsed structure search and rescue", "CCCM", "RDANA", "Early warning", "GIS", "Psychosocial first aid", "Other"]}, {"key": "count", "label": "People with the skill", "type": "integer", "required": true, "min": 0}, {"key": "last_trained", "label": "Most recent training", "type": "date", "required": false}, {"key": "lapsed", "label": "Refresher lapsed", "type": "integer", "required": false, "hint": "Number of people past their refresher date", "min": 0}]}'::jsonb,'draft',1),
('5e893536-ccb6-5114-904a-11777f2588cc'::uuid,'CAP-F02','Annual City DRRM training plan entry','Chapter 9 CAP-F02 (SOP 9-01). One course per entry; every course has an evaluation method.','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'{"fields": [{"key": "course", "label": "Course", "type": "text", "required": true}, {"key": "target_group", "label": "Target group", "type": "multiselect", "required": true, "options": ["CDRRMO staff", "EOC staff", "City offices", "BDRRMC", "Schools", "Health facilities", "Volunteers", "Partners"]}, {"key": "gap_source", "label": "Gap source", "type": "select", "required": true, "options": ["Competency matrix (Annex 9-B)", "IAT gap", "AAR finding", "Lapsed refresher", "Post-election orientation"]}, {"key": "provider", "label": "Provider", "type": "text", "required": true}, {"key": "month", "label": "Planned month", "type": "select", "required": true, "options": ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]}, {"key": "cost", "label": "Estimated cost (PHP)", "type": "integer", "required": false, "min": 0}, {"key": "evaluation", "label": "Evaluation method", "type": "select", "required": true, "options": ["Written test", "Practical assessment", "Drill observation", "Pre- and post-test", "Attendance only"]}, {"key": "ldrrmfip_line", "label": "LDRRMFIP line", "type": "text", "required": false}]}'::jsonb,'draft',1),
('79f6aa46-1aae-5d23-94ff-287b45c69439'::uuid,'CAP-F03','Training and competence record','Chapter 9 CAP-F03 (SOP 9-02). One record per course run; refresher date set on completion.','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'{"fields": [{"key": "course", "label": "Course", "type": "text", "required": true}, {"key": "date", "label": "Date", "type": "date", "required": true}, {"key": "target_group", "label": "Group", "type": "select", "required": true, "options": ["CDRRMO staff", "EOC staff", "City offices", "BDRRMC", "Schools", "Health facilities", "Volunteers", "Partners"]}, {"key": "attended", "label": "Attended", "type": "integer", "required": true, "min": 0}, {"key": "women", "label": "Of whom women", "type": "integer", "required": false, "min": 0}, {"key": "passed", "label": "Passed the evaluation", "type": "integer", "required": false, "min": 0}, {"key": "refresher_due", "label": "Refresher due", "type": "date", "required": true}, {"key": "evidence", "label": "Evidence filed", "type": "multiselect", "required": false, "options": ["Attendance sheet", "Test results", "Certificates", "Photos"]}]}'::jsonb,'draft',1),
('b6ebad6a-f42a-5023-8210-a802002b2585'::uuid,'CAP-F04','Exercise plan','Chapter 9 CAP-F04 (SOP 9-03; Annex 9-C). The protocol runs in drill mode; findings go to the AAR route (SOP 7-04).','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'{"fields": [{"key": "exercise_type", "label": "Type", "type": "select", "required": true, "options": ["Orientation", "Tabletop", "Functional (EOC)", "Full-scale", "NSED participation"]}, {"key": "scenario", "label": "Hazard scenario", "type": "select", "required": true, "options": ["Typhoon and flood", "Flash flood", "Landslide", "Earthquake", "Tsunami", "Fire", "Other"]}, {"key": "objectives", "label": "Objectives (short)", "type": "textarea", "required": true}, {"key": "protocols", "label": "MODE protocols exercised", "type": "text", "required": false}, {"key": "date", "label": "Date", "type": "date", "required": true}, {"key": "participants", "label": "Participating offices and barangays", "type": "text", "required": true}, {"key": "evaluators", "label": "Evaluators (positions)", "type": "text", "required": true}, {"key": "aar_due", "label": "AAR due", "type": "date", "required": false}]}'::jsonb,'draft',1),
('cdc09089-1018-52c9-b06e-0be9b5f24b6a'::uuid,'CAP-F05','IEC reach log and sector consultation record','Chapter 9 CAP-F05 (SOPs 9-04, 9-09). Reach is counted, not estimated.','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'{"fields": [{"key": "entry", "label": "Entry", "type": "select", "required": true, "options": ["IEC activity", "Sector consultation"]}, {"key": "channel", "label": "Channel", "type": "select", "required": true, "options": ["Barangay assembly", "School", "Radio", "Social media", "Printed material", "Sign language video", "Other"]}, {"key": "language", "label": "Language", "type": "multiselect", "required": true, "options": ["Ormocanon (Bisaya)", "English", "Filipino (Tagalog)", "Waray", "Filipino Sign Language"]}, {"key": "barangay", "label": "Barangay or venue", "type": "text", "required": true}, {"key": "reached", "label": "People reached", "type": "integer", "required": true, "min": 0}, {"key": "sectors", "label": "Sectors reached or consulted", "type": "multiselect", "required": false, "options": ["Persons with disabilities", "Older persons", "Women", "Children and youth", "Indigenous peoples", "Informal settlers", "Farmers and fisherfolk"]}, {"key": "feedback", "label": "Feedback or request raised", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('13d4fc1d-5817-5823-b622-867dc48bbf11'::uuid,'CAP-F06','BDRRMC functionality matrix entry','Chapter 9 CAP-F06 (SOP 9-06). One entry per barangay (85). Tier thresholds are set by the CDRRMC.','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'{"fields": [{"key": "barangay", "label": "Barangay", "type": "text", "required": true}, {"key": "organised", "label": "BDRRMC organised by resolution", "type": "select", "required": true, "options": ["Yes", "No", "Records not obtained"]}, {"key": "bdrrm_plan", "label": "BDRRM plan current", "type": "select", "required": true, "options": ["Yes", "No", "Records not obtained"]}, {"key": "contingency_plan", "label": "Barangay contingency plan", "type": "select", "required": true, "options": ["Yes", "No", "Records not obtained"]}, {"key": "drill", "label": "Drill in the last 12 months", "type": "select", "required": true, "options": ["Yes", "No", "Records not obtained"]}, {"key": "ews", "label": "Early warning arrangement tested", "type": "select", "required": true, "options": ["Yes", "No", "Records not obtained"]}, {"key": "fund_use", "label": "BDRRMF used as planned", "type": "select", "required": true, "options": ["Yes", "Partly", "No", "Records not obtained"]}, {"key": "tier", "label": "Tier (CDRRMC thresholds)", "type": "select", "required": false, "options": ["Tier 1", "Tier 2", "Tier 3", "Not yet tiered"]}, {"key": "support", "label": "Support package", "type": "multiselect", "required": false, "options": ["Training", "Plan review", "Drill", "Equipment check", "Mentoring by another barangay"]}]}'::jsonb,'draft',1),
('bee834a9-b118-5ee3-b79d-9c394e3b9019'::uuid,'CAP-F07','Purok welfare-check time record','Chapter 9 CAP-F07 (SOPs 9-03, 9-06). Target: every resident accounted for within 12 hours.','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'{"fields": [{"key": "barangay", "label": "Barangay", "type": "text", "required": true}, {"key": "purok", "label": "Purok", "type": "text", "required": true}, {"key": "mode", "label": "Mode", "type": "select", "required": true, "options": ["Drill", "Real event"]}, {"key": "started", "label": "Check started", "type": "datetime", "required": true}, {"key": "completed", "label": "All households accounted for", "type": "datetime", "required": false}, {"key": "households", "label": "Households checked", "type": "integer", "required": true, "min": 0}, {"key": "unaccounted", "label": "Households not yet accounted for", "type": "integer", "required": true, "min": 0}]}'::jsonb,'draft',1),
('5c431f42-0e1f-5e8d-b597-21140b4d6454'::uuid,'CAP-F08','Volunteer registry entry','Chapter 9 CAP-F08 (SOP 9-07). Role-limited access; personal data under RA 10173.','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'{"fields": [{"key": "group", "label": "Volunteer group", "type": "text", "required": true}, {"key": "skill", "label": "Main skill", "type": "select", "required": true, "options": ["Search and rescue", "First aid", "CCCM", "Logistics", "Communications", "Psychosocial support", "Other"]}, {"key": "accredited", "label": "Accreditation", "type": "select", "required": true, "options": ["Accredited", "Pending", "Lapsed"]}, {"key": "insured", "label": "Insurance valid until", "type": "date", "required": true}, {"key": "trained_on", "label": "Last training", "type": "date", "required": false}, {"key": "barangay", "label": "Home barangay", "type": "text", "required": true}, {"key": "available", "label": "Available for deployment", "type": "select", "required": true, "options": ["Yes", "No", "Limited"]}]}'::jsonb,'draft',1),
('56217476-47ac-53a1-9d19-e8773d08c54b'::uuid,'CAP-F09','Evacuation centre audit','Chapter 9 CAP-F09 (SOP 9-08; Annex 9-D). Twelve items, each met or not met with a note.','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'{"fields": [{"key": "centre", "label": "Evacuation centre", "type": "text", "required": true}, {"key": "barangay", "label": "Barangay", "type": "text", "required": true}, {"key": "centre_type", "label": "Type", "type": "select", "required": true, "options": ["Dedicated evacuation centre", "School (last resort, RA 12076)", "Covered court", "Other public building"]}, {"key": "low_risk", "label": "1. Low-risk location (current hazard maps)", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "structural", "label": "2. Structural safety assessed (Building Official)", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "capacity", "label": "3. Capacity matched to families served", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "wash", "label": "4. WASH separated by sex, accessible, maintained", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "access", "label": "5. Ground-floor priority and access", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "privacy", "label": "6. Privacy, family, women- and child-friendly spaces", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "health", "label": "7. Health and first-aid area; referral", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "security", "label": "8. Security arrangement", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "kitchen", "label": "9. Kitchen, storage and waste", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "power", "label": "10. Power backup and communications", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "signage", "label": "11. Signage in Ormocanon (Bisaya) and accessible formats", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "designated", "label": "12. Designated by City issuance", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "fixes", "label": "Improvements agreed", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('f956dc2a-6f1c-5dfe-ab95-1a243b996869'::uuid,'SUS-F01','Legal instrument tracker','Chapter 10 SUS-F01 (SOP 10-01). Status sourced to documents in the Vault.','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'{"fields": [{"key": "instrument", "label": "Instrument", "type": "select", "required": true, "options": ["DRRM ordinance amendment", "EOC Executive Order", "CDRRMC Executive Order", "Manual version", "Agreement", "Other"]}, {"key": "reference", "label": "Reference or draft title", "type": "text", "required": true}, {"key": "status", "label": "Status", "type": "select", "required": true, "options": ["Not started", "In progress", "Done", "Stalled", "Not applicable"]}, {"key": "since", "label": "In this status since", "type": "date", "required": true}, {"key": "next_step", "label": "Next step and office", "type": "text", "required": true}]}'::jsonb,'draft',1),
('f23716ca-3e72-5176-bde3-cf39041c0e79'::uuid,'SUS-F02','Annual sustainability checklist','Chapter 10 SUS-F02 (SOP 10-01). Five pillars; each needs evidence.','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'{"fields": [{"key": "year", "label": "Year", "type": "integer", "required": true, "min": 2026}, {"key": "legal", "label": "Legal and institutional permanence", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "people", "label": "People and succession", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "finance", "label": "Financial sustainability", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "continuity", "label": "Continuity of operations", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "digital", "label": "Digital continuity and information security", "type": "select", "required": true, "options": ["Met", "Partly met", "Not met", "Not checked"]}, {"key": "roadmap_updated", "label": "Resilience roadmap updated", "type": "checkbox", "required": false}, {"key": "gaps", "label": "Gaps and owners", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('bf18940d-8ad0-5832-8cc8-03f27a2eb872'::uuid,'SUS-F03','Succession order and alternates','Chapter 10 SUS-F03 (SOP 10-02). Positions, not persons; mirrors EOC designations.','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'{"fields": [{"key": "position", "label": "Position", "type": "text", "required": true}, {"key": "first_alternate", "label": "First alternate (position)", "type": "text", "required": true}, {"key": "second_alternate", "label": "Second alternate (position)", "type": "text", "required": false}, {"key": "issuance", "label": "Designating issuance", "type": "text", "required": false}, {"key": "handover_pack", "label": "Transition pack (Annex 10-C) ready", "type": "checkbox", "required": false}, {"key": "reviewed_on", "label": "Reviewed on", "type": "date", "required": true}]}'::jsonb,'draft',1),
('26c7cc82-4b2c-5467-a747-ae304d4cd1a0'::uuid,'SUS-F04','Backup, restore and access review log','Chapter 10 SUS-F04 (SOP 10-03). A backup counts only once a restore is tested.','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'{"fields": [{"key": "system", "label": "System", "type": "select", "required": true, "options": ["MODE database", "MODE files (Vault)", "City records", "Email", "Other"]}, {"key": "check", "label": "Check", "type": "select", "required": true, "options": ["Backup", "Restore test", "Access review", "Connectivity test"]}, {"key": "result", "label": "Result", "type": "select", "required": true, "options": ["Passed", "Failed", "Partly passed"]}, {"key": "done_on", "label": "Done on", "type": "date", "required": true}, {"key": "accounts_removed", "label": "Accounts removed or changed", "type": "integer", "required": false, "min": 0}, {"key": "follow_up", "label": "Follow-up", "type": "text", "required": false}]}'::jsonb,'draft',1),
('6c762f62-234e-5f0d-b9b8-7d22af3e111a'::uuid,'SUS-F05','Annual continuity check','Chapter 10 SUS-F05 (SOP 10-04). Alternate EOC items only where one is designated.','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'{"fields": [{"key": "year", "label": "Year", "type": "integer", "required": true, "min": 2026}, {"key": "eoc_self_check", "label": "EOC readiness self-check done", "type": "select", "required": true, "options": ["Yes", "No"]}, {"key": "alternate_eoc", "label": "Alternate EOC", "type": "select", "required": true, "options": ["Designated and relocation tested", "Designated, not tested", "Not designated (N/A)"]}, {"key": "pscp_exercise", "label": "PSCP exercise", "type": "select", "required": true, "options": ["Done", "Planned", "Not done"]}, {"key": "power_hours", "label": "Backup power endurance (hours)", "type": "integer", "required": false, "min": 0}, {"key": "findings", "label": "Findings to CAPA", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('70de626e-c7c8-50bd-8889-7c091313bf8f'::uuid,'SUS-F06','Recognition submission and results tracker','Chapter 10 SUS-F06 (SOP 10-05). Gawad KALASAG CY 2026 and SGLG; gaps go to CAPA.','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'{"fields": [{"key": "programme", "label": "Programme", "type": "select", "required": true, "options": ["Gawad KALASAG (LDRRMC)", "Seal of Good Local Governance", "Other"]}, {"key": "cycle", "label": "Cycle", "type": "text", "required": true}, {"key": "stage", "label": "Stage", "type": "select", "required": true, "options": ["Self-check", "Submitted", "Validated", "Result received"]}, {"key": "result", "label": "Result", "type": "text", "required": false}, {"key": "gaps", "label": "Gaps found", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('ef1bb04f-abeb-566e-8c39-f8bbfec6d8b4'::uuid,'SUS-F07','Innovation pilot proposal and evaluation','Chapter 10 SUS-F07 (SOP 10-06). A pilot has a measure and an end date.','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'{"fields": [{"key": "idea", "label": "Idea", "type": "text", "required": true}, {"key": "problem", "label": "Problem it addresses", "type": "text", "required": true}, {"key": "source", "label": "Source", "type": "select", "required": true, "options": ["AAR", "IAT gap", "Staff suggestion", "Partner", "Good practice elsewhere"]}, {"key": "measure", "label": "Measure of success", "type": "text", "required": true}, {"key": "end_date", "label": "Pilot ends", "type": "date", "required": true}, {"key": "decision", "label": "Decision", "type": "select", "required": false, "options": ["Adopt", "Adapt and re-test", "Drop"]}]}'::jsonb,'draft',1)
insert into public.protocol_templates (id,code,title,purpose,trigger_text,document_id,owner_role,category,status,template_rev,kind,sop_ref,process_owner,policy_refs,indicator_ids) values
('b7a1102f-fbbb-5417-9930-7dec45570040'::uuid,'WF-SOP9-01','SOP 9-01 Training Needs Analysis, Skills Inventory and Annual City DRRM Training Plan','Base the City''s DRRM training on measured needs across offices, barangays, schools, responders and volunteers, and know each year what skills the City has. Draft for validation; not yet validated by the CDRRMO.','Annual planning cycle (before the budget call); after a barangay election; after an AAR with training findings','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'cdrrmo_head'::public.app_role,'capacity','draft',1,'workflow','SOP 9-01 (MOO Ch.9 Consolidated Draft 1.0)','CDRRMO Administration and Training',array['RA 10121 Secs. 12(c), 14','CDRRMC Res. No. 09, s. 2024']::text[],array['A7.1','A2.10','A2.6']::text[]),
('6666a78b-6d81-5d7a-b36b-1aadb9db2e15'::uuid,'WF-SOP9-02','SOP 9-02 Training Delivery, Competence Records and Refresher Cycle','Deliver training that produces competence, keep verifiable records, and refresh skills before they lapse. Draft for validation; not yet validated by the CDRRMO.','Each scheduled course; a refresher date reached; a new BDRRMC after an election','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'cdrrmo_head'::public.app_role,'capacity','draft',1,'workflow','SOP 9-02 (MOO Ch.9 Consolidated Draft 1.0)','CDRRMO Administration and Training',array['RA 10121 Sec. 14','NDRRMC MC No. 4, s. 2012']::text[],array['A7.1','A7.8','B7.2']::text[]),
('f23eca33-3534-5631-a42c-42168ef08564'::uuid,'WF-SOP9-03','SOP 9-03 Annual Exercise Programme: Planning, Conduct and Follow-Up','Test plans, the EOC and people in a planned progression every year, and turn the findings into improvements. Draft for validation; not yet validated by the CDRRMO.','Annual planning; NSED schedule; new or revised contingency plan; AAR finding','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'cdrrmo_head'::public.app_role,'capacity','draft',1,'workflow','SOP 9-03 (MOO Ch.9 Consolidated Draft 1.0)','CDRRMO Administration and Training',array['NDRRMC NSED guidelines','EOC Capability Assessment Checklist','RA 10121']::text[],array['A7.2','B7.3','A7.7','A7.9']::text[]),
('d23764ed-5c26-5d94-a48f-c5b913c14ae4'::uuid,'WF-SOP9-04','SOP 9-04 Public Awareness (IEC) Programme With Reach Targets','Reach every barangay each year with clear, accessible preparedness messages, and measure the reach. Draft for validation; not yet validated by the CDRRMO.','Annual planning; start of the typhoon season; NSED; new hazard information','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'cdrrmo_head'::public.app_role,'capacity','draft',1,'workflow','SOP 9-04 (MOO Ch.9 Consolidated Draft 1.0)','CDRRMO Administration and Training',array['RA 10121 Sec. 12(c)','RA 11106','RA 7277 as amended','RA 10639']::text[],array['A6.6','A6.4','A7.6']::text[]),
('4ac48f2b-5d86-545d-a292-ce86c3c6ae11'::uuid,'WF-SOP9-05','SOP 9-05 Risk Communication Plan and Public Information Officer','Have a designated PIO and an approved plan for consistent, accurate and inclusive public communication, including rumour management. Draft for validation; not yet validated by the CDRRMO.','Adoption of this chapter; annual review; change of PIO; AAR finding on communication','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'cdrrmo_head'::public.app_role,'capacity','draft',1,'workflow','SOP 9-05 (MOO Ch.9 Consolidated Draft 1.0)','CDRRMO Head',array['RA 10121','RA 11106','RA 10173']::text[],array['A6.5','A6.4']::text[]),
('67a65413-b469-5c50-9c61-f9b194ac0cf3'::uuid,'WF-SOP9-06','SOP 9-06 BDRRMC Functionality Assessment and Tiered Support','Know each year how well each of the 85 BDRRMCs functions and support the weakest first. Draft for validation; not yet validated by the CDRRMO.','Annual cycle; after a barangay election; after an event that exposed a weakness','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'cdrrmo_head'::public.app_role,'capacity','draft',1,'workflow','SOP 9-06 (MOO Ch.9 Consolidated Draft 1.0)','CDRRMO Research and Planning',array['RA 10121','DILG MC No. 2025-035 (Listo si KAP)','Ordinance No. 171, s. 2024']::text[],array['A7.3','A7.9','A3.7']::text[]),
('2a2ce647-0e12-5189-988d-735a4d006724'::uuid,'WF-SOP9-07','SOP 9-07 Volunteer Programme: Recruitment, Accreditation, Registry, Training, Insurance and Deployment','Keep a trained, insured and accredited volunteer reserve that can be tasked safely through the EOC. Draft for validation; not yet validated by the CDRRMO.','Annual recruitment; an organisation''s request for accreditation; an activation; a spontaneous volunteer influx','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'cdrrmo_head'::public.app_role,'capacity','draft',1,'workflow','SOP 9-07 (MOO Ch.9 Consolidated Draft 1.0)','CDRRMO Administration and Training',array['RA 10121 Sec. 13','RA 9418','Ordinance No. 160, s. 2024','CDRRMC Res. Nos. 03–04, s. 2022 and No. 07, s. 2024','RA 12287 IRR Rule IV Sec. 5']::text[],array['A2.8']::text[]),
('592e6fcc-1412-5010-87b6-97e5297faf35'::uuid,'WF-SOP9-08','SOP 9-08 Evacuation Centre Standards Audit and Improvement','Know whether each evacuation centre meets the standards and improve them in priority order. Draft for validation; not yet validated by the CDRRMO.','Annual cycle; a new or changed evacuation centre; an AAR finding on a centre','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'cdrrmo_head'::public.app_role,'capacity','draft',1,'workflow','SOP 9-08 (MOO Ch.9 Consolidated Draft 1.0)','CDRRMO Research and Planning',array['RA 12076','DSWD standards','NDRRMC Disaster Preparedness Minimum Standards Vol. 2','RA 10821','RA 7277 as amended']::text[],array['A7.4','C2.1']::text[]),
('6c4b14de-4925-51db-882d-19e2c77fa156'::uuid,'WF-SOP9-09','SOP 9-09 Sector Consultation on Inclusive DRRM','Hear each year from women, children and youth, older persons, persons with disabilities and other at-risk groups whether they were engaged, and act on what they say. Draft for validation; not yet validated by the CDRRMO.','Annual cycle, before the IAT cycle; after a major event','57e7eec1-e655-50fd-8bc4-e7b956b654fc'::uuid,'cdrrmo_head'::public.app_role,'capacity','draft',1,'workflow','SOP 9-09 (MOO Ch.9 Consolidated Draft 1.0)','CDRRMO Head',array['RA 9710','RA 7277 as amended','RA 9994','RA 10821','RA 8371','RA 12287 IRR Rule IV Sec. 1(a)']::text[],array['A7.6','A6.4']::text[]),
('5fa93c9e-9092-547b-9b8c-33cf9047f2f2'::uuid,'WF-SOP10-01','SOP 10-01 Annual Sustainability Review and Resilience Roadmap Update','Check each year that the legal, human, financial, digital and knowledge foundations are in place, and update the roadmap. Draft for validation; not yet validated by the CDRRMO.','First quarter of each year, after the IAT cycle closes and the annual results report is presented','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'cdrrmo_head'::public.app_role,'sustainability','draft',1,'workflow','SOP 10-01 (MOO Ch.10 Consolidated Draft 1.0)','CDRRMO Research and Planning',array['RA 10121 Secs. 11–12','JMC 2014-1','Ordinance No. 008, s. 2014 as amended']::text[],array['A1.1','A2.3','B7.5']::text[]),
('b5b4a153-07f4-5744-8b18-a48deb76e309'::uuid,'PR-LEADERSHIP-TRANSITION','SOP 10-02 Leadership Transition and Succession','Keep DRRM functions continuous through elections, changes of the CDRRMO Head and absences of key officers. Draft for validation; not yet validated by the CDRRMO.','After each local election; appointment of a new CDRRMO Head; absence of a key officer beyond the period set in the succession order','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'eoc_manager'::public.app_role,'sustainability','draft',1,'protocol','SOP 10-02 (MOO Ch.10 Consolidated Draft 1.0)','CDRRMO Head; City Administrator',array['RA 7160','Civil Service rules on designation','RA 10121 Sec. 12']::text[],array['A2.2','B4.2']::text[]),
('1c90a287-658f-5e7a-9de5-0419872ebc26'::uuid,'WF-SOP10-03','SOP 10-03 Digital Continuity: Backup, Restore Test, Access Review and Connectivity','Make sure MODE and the EOC''s digital systems can be recovered and stay secure. Draft for validation; not yet validated by the CDRRMO.','Weekly, quarterly and annual schedule; a security incident; a change of hosting or custodian','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'cdrrmo_head'::public.app_role,'continuity','draft',1,'workflow','SOP 10-03 (MOO Ch.10 Consolidated Draft 1.0)','City ICT office',array['RA 10173','NPC Circulars No. 2023-06 and No. 16-03','ADR-002, ADR-021, ADR-026']::text[],array['B3.3','B3.5']::text[]),
('8a479eb7-45d3-5b93-b7cd-3f9d3134fc78'::uuid,'WF-SOP10-04','SOP 10-04 Annual Continuity Check: Alternate EOC Relocation, PSCP Exercise and EOC Readiness Self-Check','Prove once a year that essential DRRM functions continue if the EOC, its power, its network or its people are lost. Draft for validation; not yet validated by the CDRRMO.','Annual schedule, before the typhoon season; a change of EOC site; an AAR finding on continuity','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'eoc_manager'::public.app_role,'continuity','draft',1,'workflow','SOP 10-04 (MOO Ch.10 Consolidated Draft 1.0)','CDRRMO Head; EOC Manager',array['NDRRMC Memo No. 131, s. 2018','PSCP Guidebook','EOC Capability Assessment Checklist (OCD, 2017)']::text[],array['B2.7','A3.4','B7.6']::text[]),
('4697fbd7-fe28-50d7-879a-2614259ea149'::uuid,'WF-SOP10-05','SOP 10-05 Recognition Systems: Gawad KALASAG and SGLG Participation and Gap Follow-Up','Take part each year with complete, truthful evidence, and turn every gap found into an improvement. Draft for validation; not yet validated by the CDRRMO.','OCD and DILG calls for submission; release of results','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'cdrrmo_head'::public.app_role,'sustainability','draft',1,'workflow','SOP 10-05 (MOO Ch.10 Consolidated Draft 1.0)','CDRRMO Research and Planning',array['NDRRMC MC No. 03, s. 2025','OCD Memo No. 763, s. 2026','RA 11292']::text[],array['A10.7']::text[]),
('96a287a8-95f8-5e9a-845b-b9fae43077a7'::uuid,'WF-SOP10-06','SOP 10-06 Innovation and Good-Practice Pipeline','Try new ideas safely, evaluate them, and adopt only what works. Draft for validation; not yet validated by the CDRRMO.','A proposal from staff, a partner or a peer exchange; an AAR or IAT gap that existing methods have not closed','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'cdrrmo_head'::public.app_role,'sustainability','draft',1,'workflow','SOP 10-06 (MOO Ch.10 Consolidated Draft 1.0)','CDRRMO Research and Planning',array['RA 10121','RA 10173','UNDRR Scorecard']::text[],array['A10.9','A10.7']::text[]),
('1a8580ca-d39e-5129-9578-810919685f26'::uuid,'WF-SOP10-07','SOP 10-07 Stewardship and Handover of the Manual and MODE','Leave the City in full control of the Manual and MODE, with no dependence on the developer. Draft for validation; not yet validated by the CDRRMO.','End of the engagement; change of the City custodian; change of hosting','11fd6dcf-233f-59ef-9607-d25f0953ebe4'::uuid,'cdrrmo_head'::public.app_role,'sustainability','draft',1,'workflow','SOP 10-07 (MOO Ch.10 Consolidated Draft 1.0)','CDRRMO Head; City ICT office',array['Engagement contract','RA 10173','RA 9470','ADR-002']::text[],array['B7.1','B3.5']::text[])
insert into public.protocol_steps (id,template_id,seq,instruction,is_critical,requires_note,due_offset_minutes,form_code) values
('4c1948cb-4e5e-55e3-b0da-96be193c660d'::uuid,'b7a1102f-fbbb-5417-9930-7dec45570040'::uuid,1,'Update the skills inventory (Administration and Training with offices and BDRRMCs). Collect counts of people with each DRRM skill by office and barangay, with last training date. Check: All offices and barangays reported? Blank means "not reported". Record: CAP-F01 inventory. [When: By March, Escalate to: CDRRMO Head]',false,true,null,'CAP-F01'),
('3e965245-b42c-5e9f-a06f-41fb2b0c57d4'::uuid,'b7a1102f-fbbb-5417-9930-7dec45570040'::uuid,2,'Analyse needs (Administration and Training). Compare the competency matrix (Annex 9-B) with the inventory, IAT gaps, AAR findings and lapsed refreshers; include CDRRMO staff needs from HR-04. Check: Each gap traced to a role and a source? Record: Needs analysis. [When: By April, Escalate to: CDRRMO Head]',true,true,null,'STEP-RECORD'),
('73572cf2-4195-5d4e-bfd4-a0293e63df9f'::uuid,'b7a1102f-fbbb-5417-9930-7dec45570040'::uuid,3,'Draft the plan (Administration and Training). List courses, target groups, providers, dates, cost and evaluation method; include refreshers and post-election orientation. Check: Every course has an evaluation method? Record: CAP-F02 draft plan. [When: By May, Escalate to: CDRRMO Head]',false,true,null,'CAP-F02'),
('83e41a9f-bb34-53f3-8918-cd471aca0b80'::uuid,'b7a1102f-fbbb-5417-9930-7dec45570040'::uuid,4,'Approve and fund (CDRRMO Head; CDRRMC). Approve; include the cost in the LDRRMFIP. Check: Funded? Record: Approved plan; LDRRMFIP line. [When: With the budget call, Escalate to: CDRRMC]',true,true,null,'STEP-RECORD'),
('dbfe06ca-48f2-5de8-8de6-10cc88be8adb'::uuid,'b7a1102f-fbbb-5417-9930-7dec45570040'::uuid,5,'Publish (Administration and Training). Publish the calendar to offices, barangays and partners. Check: Sent to all target groups? Record: Training calendar. [When: Before the year starts, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('3cc4c0c0-46fe-5700-a564-4dd798741d7a'::uuid,'6666a78b-6d81-5d7a-b36b-1aadb9db2e15'::uuid,1,'Prepare (Course lead). Confirm objectives, competencies, trainers, venue, materials (local language and accessible), and participant list by position. Check: Accessible formats ready? Record: Course file. [When: Two weeks before, Escalate to: Administration and Training]',false,true,null,'STEP-RECORD'),
('e327667e-cc88-5e6b-822a-a644f1b0e6e6'::uuid,'6666a78b-6d81-5d7a-b36b-1aadb9db2e15'::uuid,2,'Deliver (Trainers). Run the course with practical exercises. Check: Practical component included? Record: Attendance. [When: As scheduled, Escalate to: Course lead]',false,true,null,'STEP-RECORD'),
('b16d28b3-6072-585f-98fe-c40c7e88a106'::uuid,'6666a78b-6d81-5d7a-b36b-1aadb9db2e15'::uuid,3,'Assess (Trainers). Assess each participant against the competency. Check: Competent, or needs further training? Record: Assessment results. [When: End of course, Escalate to: Course lead]',false,true,null,'STEP-RECORD'),
('51a07163-477b-52b3-98e7-87572abac2c2'::uuid,'6666a78b-6d81-5d7a-b36b-1aadb9db2e15'::uuid,4,'Record (Administration and Training). Enter course, participant (position, office or barangay), competency, result and refresher date on CAP-F03; send City employees'' records to the HRMO. Check: Refresher date set? Record: CAP-F03 entries. [When: Within 10 days, Escalate to: CDRRMO Head]',false,true,null,'CAP-F03'),
('34096729-8b91-58d7-a187-b51978d1d15c'::uuid,'6666a78b-6d81-5d7a-b36b-1aadb9db2e15'::uuid,5,'Track refreshers (Administration and Training). Each quarter, list people whose refresher is due within 90 days or lapsed; schedule them. Check: Lapsed refreshers in safety-critical roles? Remove from active deployment lists until refreshed. Record: Refresher list. [When: Quarterly, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('a5eeba21-1ab3-57bd-a344-07fa54afd038'::uuid,'6666a78b-6d81-5d7a-b36b-1aadb9db2e15'::uuid,6,'Evaluate (Administration and Training). Check whether trained people performed in exercises and events (Chapter 7 AARs). Check: Training effective? Record: Course evaluation. [When: Annually, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('67046eb5-e8b7-5e00-b3ee-f8cce061395e'::uuid,'f23eca33-3534-5631-a42c-42168ef08564'::uuid,1,'Plan the year (Administration and Training). Set the programme from Table 9.6: which plans, hazards, barangays and partners each exercise covers. Check: Each priority hazard and the EOC covered? Record: Annual exercise programme. [When: With the training plan, Escalate to: CDRRMC]',false,true,null,'STEP-RECORD'),
('581f271e-d7c4-5901-85f2-a279a2d25f4b'::uuid,'f23eca33-3534-5631-a42c-42168ef08564'::uuid,2,'Design the exercise (Exercise director). Write objectives, scenario, participants, safety rules, evaluator list and exercise control (CAP-F04). Check: Objectives measurable? Record: CAP-F04 exercise plan. [When: Six weeks before (two for drills), Escalate to: CDRRMO Head]',false,true,null,'CAP-F04'),
('064a6922-8021-5b25-824f-9ca11b564cd5'::uuid,'f23eca33-3534-5631-a42c-42168ef08564'::uuid,3,'Prepare (Exercise director). Brief players and evaluators; inform the public and partners where needed; prepare MODE protocols in drill mode. Check: Public informed where the exercise is visible? Record: Briefings; notices. [When: One week before, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('9517b100-c075-565e-898b-6acfffffe358'::uuid,'f23eca33-3534-5631-a42c-42168ef08564'::uuid,4,'Conduct (Exercise director; controllers). Run the exercise; stop it if real safety is at risk or a real event occurs. Check: Real event? Stop and switch to operations. Record: Logs; protocol runs. [When: As scheduled, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('8db4a02f-4322-5383-9894-a2a92378b3e2'::uuid,'f23eca33-3534-5631-a42c-42168ef08564'::uuid,5,'Hot wash (Exercise director). Collect immediate observations from players and evaluators. Check: All teams heard? Record: Hot-wash notes. [When: End of exercise, Escalate to: —]',false,true,null,'STEP-RECORD'),
('d6c9a53b-dfe1-5ed7-b366-6697fece8006'::uuid,'f23eca33-3534-5631-a42c-42168ef08564'::uuid,6,'Evaluate (Evaluators; M&E unit). Evaluate against objectives under Chapter 7 (SOP 7-04); time the welfare check where included. Check: Findings with evidence? Record: ME-F04 report; CAP-F07 times. [When: Within the Chapter 7 timing, Escalate to: CDRRMO Head]',false,true,null,'CAP-F07'),
('1e074bb8-b6d5-5fcc-8eb3-28d8a5c86cfa'::uuid,'f23eca33-3534-5631-a42c-42168ef08564'::uuid,7,'Follow up (M&E unit). Enter actions in the CAPA register; feed the training plan. Check: Every finding has an action? Record: ME-F05 entries. [When: Within 5 days of approval, Escalate to: CDRRMC]',false,true,null,'STEP-RECORD'),
('7ff6d644-5618-5c0a-af6e-4480d2074163'::uuid,'d23764ed-5c26-5d94-a48f-c5b913c14ae4'::uuid,1,'Set targets (Administration and Training). Set messages, audiences, channels and reach targets per barangay; prioritise the most exposed barangays. Check: Targets per barangay set? Record: CAP-F05 programme. [When: By February, Escalate to: CDRRMO Head]',false,true,null,'CAP-F05'),
('185ed67f-4327-5896-8abe-a260924ea2e6'::uuid,'d23764ed-5c26-5d94-a48f-c5b913c14ae4'::uuid,2,'Develop materials (Administration and Training with sector groups). Write in Ormocanon (Bisaya); produce FSL, large-print, pictorial and audio versions; test with residents. Check: Understood by test groups? Record: Tested materials. [When: By March, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('4f1a6142-7ee9-5306-80c8-42e114995141'::uuid,'d23764ed-5c26-5d94-a48f-c5b913c14ae4'::uuid,3,'Deliver (Administration and Training; BDRRMCs; schools; partners). Run activities by channel; count reach by barangay, sex and age group where possible. Check: On track by mid-year? Record: Reach log. [When: Through the year, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('928b2dec-4fb0-54bd-a91a-2ae892565628'::uuid,'d23764ed-5c26-5d94-a48f-c5b913c14ae4'::uuid,4,'Check knowledge (Research and Planning). Run a short knowledge check in a sample of barangays. Check: Key messages understood? Record: Knowledge check results. [When: Annually, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('23106d7e-667c-551f-8172-35f8e6cddc95'::uuid,'d23764ed-5c26-5d94-a48f-c5b913c14ae4'::uuid,5,'Report (Administration and Training). Report reach against targets in the annual results report (Chapter 7). Check: Targets met? If not, why? Record: IEC report. [When: December, Escalate to: CDRRMC]',false,true,null,'STEP-RECORD'),
('6cc9439e-64b9-5680-bb52-d28ac60685f7'::uuid,'4ac48f2b-5d86-545d-a292-ce86c3c6ae11'::uuid,1,'Designate (City Mayor). Designate the DRRM PIO and an alternate. Check: Designated in writing? Record: Office order. [When: Within 30 days of adoption, Escalate to: —]',true,true,null,'STEP-RECORD'),
('0829b336-3cd8-52a6-9f94-9bb28c3f8b4f'::uuid,'4ac48f2b-5d86-545d-a292-ce86c3c6ae11'::uuid,2,'Draft the plan (PIO with City Information Office). Set spokespersons, message approval, media relations, channels, accessibility, rumour monitoring and correction, and coordination with Chapter 4. Check: Consistent with Chapter 4? Record: Draft plan. [When: Within 60 days, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('b05cd603-6cb9-56f0-a317-67c9cf95061d'::uuid,'4ac48f2b-5d86-545d-a292-ce86c3c6ae11'::uuid,3,'Approve (City Mayor). Approve the plan. Check: Approved? Record: Approved plan. [When: Within 90 days, Escalate to: —]',true,true,null,'STEP-RECORD'),
('a20fb6af-d216-5762-8533-eb2b263a8b8c'::uuid,'4ac48f2b-5d86-545d-a292-ce86c3c6ae11'::uuid,4,'Practise (PIO). Use the plan in exercises (SOP 9-03), including a misinformation scenario. Check: Worked under exercise conditions? Record: Exercise findings. [When: Annually, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('99abcaa0-d0b6-5b2c-b99c-183952781b13'::uuid,'4ac48f2b-5d86-545d-a292-ce86c3c6ae11'::uuid,5,'Review (PIO). Review the plan each year and after events. Check: Changes needed? Record: Revised plan. [When: Annually, Escalate to: City Mayor]',false,true,null,'STEP-RECORD'),
('5bd4bddc-9b4b-5356-8816-7cda65cf20b0'::uuid,'67a65413-b469-5c50-9c61-f9b194ac0cf3'::uuid,1,'Assess (Research and Planning with DILG City Office). Assess all 85 BDRRMCs on CAP-F06, using Listo si KAP results where available. Check: All 85 assessed? Blank means "not assessed". Record: CAP-F06 matrix. [When: By March, Escalate to: DILG City Director]',false,true,null,'CAP-F06'),
('66398a7c-86b9-567a-b352-78d212dfbe8b'::uuid,'67a65413-b469-5c50-9c61-f9b194ac0cf3'::uuid,2,'Tier (Research and Planning). Group barangays into support tiers using thresholds set by the CDRRMC and CDRA exposure. Check: Most exposed low-functioning barangays first? Record: Tier list. [When: By April, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('142e873b-f3d0-5771-ad0d-52b2d19ad8bc'::uuid,'67a65413-b469-5c50-9c61-f9b194ac0cf3'::uuid,3,'Plan support (Research and Planning with Administration and Training). Agree a support package per tier: training, plan review, drill, equipment check, mentoring by higher-tier barangays. Check: Resources available? Record: Support plan. [When: By May, Escalate to: CDRRMC]',false,true,null,'STEP-RECORD'),
('dce16a44-ddea-5414-abe0-83dd6ab9913e'::uuid,'67a65413-b469-5c50-9c61-f9b194ac0cf3'::uuid,4,'Deliver (CDRRMO teams; peer mentors). Deliver support; include a timed purok welfare check in each barangay''s drill. Check: Welfare check within 12 hours? Record: Visit records; CAP-F07 times. [When: Through the year, Escalate to: CDRRMO Head]',false,true,null,'CAP-F07'),
('b6a1a72d-5c84-5901-9dc0-7db20c7e749f'::uuid,'67a65413-b469-5c50-9c61-f9b194ac0cf3'::uuid,5,'Re-assess and report (Research and Planning). Re-assess next year; report change by tier to the CDRRMC. Check: Did the weakest improve? Record: Report. [When: Annually, Escalate to: CDRRMC]',false,true,null,'STEP-RECORD'),
('d1a92d2b-6bff-5893-962b-726008d0ed94'::uuid,'2a2ce647-0e12-5189-988d-735a4d006724'::uuid,1,'Recruit (Administration and Training). Invite individuals and organisations; state roles, requirements and commitments. Check: Eligible? Record: Applications. [When: Annually, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('0a504ccf-1c95-52ba-bf77-f4862f74b513'::uuid,'2a2ce647-0e12-5189-988d-735a4d006724'::uuid,2,'Train and accredit (Administration and Training; CDRRMC). Train applicants; CDRRMC accredits those who pass. Check: Competent? Record: Accreditation resolution. [When: Per cycle, Escalate to: CDRRMC]',true,true,null,'STEP-RECORD'),
('faea8b42-d302-599b-bd81-5cd3b60333ca'::uuid,'2a2ce647-0e12-5189-988d-735a4d006724'::uuid,3,'Register and insure (Administration and Training). Enter accredited volunteers on CAP-F08 with skills, availability, insurance category and expiry. Check: Insured before deployment? Record: CAP-F08 registry; insurance cover. [When: On accreditation, Escalate to: CDRRMO Head]',false,true,null,'CAP-F08'),
('f1feae06-901e-566c-944a-d5c340e5a662'::uuid,'2a2ce647-0e12-5189-988d-735a4d006724'::uuid,4,'Deploy (EOC or Incident Commander). Task volunteers through the EOC or IC; brief on safety; record check-in and check-out. Check: Task within training and insurance? Record: Deployment records. [When: During activation or AA, Escalate to: EOC Manager]',false,true,null,'STEP-RECORD'),
('031b2794-c5ad-5d48-9c3b-604f89e2a8f4'::uuid,'2a2ce647-0e12-5189-988d-735a4d006724'::uuid,5,'Manage spontaneous volunteers (EOC Logistics). Register at one point; task to safe roles or redirect. Check: Safe and useful task available? Record: Spontaneous volunteer log. [When: During events, Escalate to: EOC Manager]',false,true,null,'STEP-RECORD'),
('9bd40632-995b-5d11-9040-e15a8767de85'::uuid,'2a2ce647-0e12-5189-988d-735a4d006724'::uuid,6,'Refresh and review (Administration and Training). Refresh training yearly; renew insurance; review the registry. Check: Lapsed? Mark inactive. Record: Updated registry. [When: Annually, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('1f8f2bd0-b107-5126-98f5-e5c32b5da629'::uuid,'592e6fcc-1412-5010-87b6-97e5297faf35'::uuid,1,'List centres (Research and Planning with CSWDO). List all designated evacuation centres with capacity, barangays served and owner. Check: List matches Chapter 4 plans? Record: EC register. [When: By February, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('ae66f2b5-2c91-5c5d-81b1-3edf4e81d9a8'::uuid,'592e6fcc-1412-5010-87b6-97e5297faf35'::uuid,2,'Audit (Audit team (CDRRMO, CSWDO, barangay)). Check each centre against Annex 9-D; request the Building Official''s structural assessment. Check: Each item checked with evidence? Record: CAP-F09 audit. [When: March–April, Escalate to: CDRRMO Head]',false,true,null,'CAP-F09'),
('83970d42-b218-5003-99c0-1312381e5169'::uuid,'592e6fcc-1412-5010-87b6-97e5297faf35'::uuid,3,'Prioritise (Research and Planning). Rank gaps by life-safety, exposure (46 critical flood barangays; CDRA "Poor" ratings) and number served. Check: Ranking agreed? Record: Priority list. [When: By May, Escalate to: CDRRMC]',true,true,null,'STEP-RECORD'),
('bb3ed47e-e567-5b7b-b87d-a40b9e2f6120'::uuid,'592e6fcc-1412-5010-87b6-97e5297faf35'::uuid,4,'Fund and improve (CDRRMO with City Engineer and CSWDO). Put retrofits in the LDRRMFIP; deliver works and supplies. Check: Funded? Record: LDRRMFIP lines; completed works. [When: Per budget cycle, Escalate to: CDRRMC]',false,true,null,'STEP-RECORD'),
('b0b16b52-8ec1-5b9d-bfc9-5ac09101ecd6'::uuid,'592e6fcc-1412-5010-87b6-97e5297faf35'::uuid,5,'Re-audit (Audit team). Re-audit improved centres and report. Check: Standards met? Record: Updated CAP-F09. [When: Annually, Escalate to: CDRRMC]',false,true,null,'CAP-F09'),
('ee848156-8ec6-5df2-a61c-3abcff25dfa6'::uuid,'6c4b14de-4925-51db-882d-19e2c77fa156'::uuid,1,'Invite (CDRRMO with IPGDO, PDAO, OSCA). Invite sector representatives; arrange accessible venue, interpreters and materials. Check: Each sector represented? Record: Invitations. [When: Annually, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('fb568115-1789-5a7c-bc49-77b030f0afc3'::uuid,'6c4b14de-4925-51db-882d-19e2c77fa156'::uuid,2,'Consult (Facilitator). Ask whether they were engaged in plans, trainings, drills and EC improvements, and what should change. Check: All voices heard? Record: Consultation record. [When: Session, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('b24c646c-b88c-5cf2-a852-6db37deb178a'::uuid,'6c4b14de-4925-51db-882d-19e2c77fa156'::uuid,3,'Act (CDRRMO Head). Decide on changes; enter them in the CAPA register; report back to participants. Check: Changes assigned? Record: ME-F05 entries; feedback to participants. [When: Within 30 days, Escalate to: CDRRMC]',true,true,null,'STEP-RECORD'),
('ea07f2c2-f7de-58e1-afbf-7d79ef6c6197'::uuid,'5fa93c9e-9092-547b-9b8c-33cf9047f2f2'::uuid,1,'Track instruments (Research and Planning). Record the status of each legal instrument: ordinance amendment, EOC EO, CDRRMC EO, Manual version, agreements. Check: Any instrument stalled for more than a year? Record: SUS-F01 tracker. [When: January, Escalate to: CDRRMO Head]',false,true,null,'SUS-F01'),
('dc51bf67-9d4c-5d51-8b61-53fde0528af0'::uuid,'5fa93c9e-9092-547b-9b8c-33cf9047f2f2'::uuid,2,'Check the pillars (Research and Planning with division chiefs). Check people (plantilla, alternates, succession), finance (lines in use), digital (SOP 10-03 results), knowledge (Manual, lessons, register). Check: Each pillar has evidence? Record: SUS-F02 checklist. [When: February, Escalate to: CDRRMO Head]',false,true,null,'SUS-F02'),
('1f6a6afe-86c3-5a51-b06f-3997a446542c'::uuid,'5fa93c9e-9092-547b-9b8c-33cf9047f2f2'::uuid,3,'Read the results (Research and Planning). Compare IAT results, the Interface Index, recognition results and the annual results report with last year. Check: Progress or slippage? Record: Analysis. [When: February, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('60e69bcc-d3da-5c8a-a2f1-b316d4006779'::uuid,'5fa93c9e-9092-547b-9b8c-33cf9047f2f2'::uuid,4,'Update the roadmap (CDRRMO Head). Propose next year''s priorities by horizon and Pareto tier; propose targets for CDRRMC decision. Check: Priorities funded or fundable? Record: Roadmap update. [When: March, Escalate to: CDRRMC]',true,true,null,'STEP-RECORD'),
('a1ec3714-86c8-52b1-ad70-710c8f10ee8d'::uuid,'5fa93c9e-9092-547b-9b8c-33cf9047f2f2'::uuid,5,'Decide and record (CDRRMC). Approve the roadmap update and targets; enter gaps in the CAPA register. Check: Approved? Record: CDRRMC resolution; ME-F05 entries. [When: First quarter meeting, Escalate to: CDRRMC Chair]',true,true,null,'STEP-RECORD'),
('69c879f1-6e5d-51c3-907d-9bd0dfd02a98'::uuid,'b5b4a153-07f4-5744-8b18-a48deb76e309'::uuid,1,'Keep the succession order current (CDRRMO Head with HRMO). Keep a written order of succession and alternates for the Head, division chiefs, EOC Manager and duty officers. Check: Every critical role has an alternate? Record: SUS-F03 succession order. [When: Reviewed each January, Escalate to: City Mayor]',true,true,null,'SUS-F03'),
('3f418f09-b8a0-56dc-87e0-fbc094566b4b'::uuid,'b5b4a153-07f4-5744-8b18-a48deb76e309'::uuid,2,'Prepare the briefing pack (CDRRMO Head). Prepare the transition pack (Annex 10-C): risks, Manual, open CAPA items, budget lines, declarations in force, agreements, designations to reissue. Check: Pack complete? Record: Transition pack. [When: Before an election or a handover, Escalate to: CDRRMO Head]',true,true,null,'STEP-RECORD'),
('37c5b065-74a7-5997-8a4a-738f1fdb58a6'::uuid,'b5b4a153-07f4-5744-8b18-a48deb76e309'::uuid,3,'Act in the interim (Designated alternate). On absence or vacancy, act under the succession order; inform the EOC roster. Check: Authority to act confirmed in writing? Record: Designation or office order. [When: Immediately, Escalate to: City Mayor]',false,true,null,'STEP-RECORD'),
('5a4232f4-510f-567e-981e-5bc0c32ff07b'::uuid,'b5b4a153-07f4-5744-8b18-a48deb76e309'::uuid,4,'Brief the new leadership (CDRRMO Head or OIC). Brief the incoming Mayor, CDRRMC and Head; walk through the Manual and MODE roles. Check: Briefing held? Record: Briefing record. [When: Within 30 days of assumption, Escalate to: City Administrator]',true,true,null,'STEP-RECORD'),
('bb51289b-6f6e-5079-a81b-dafd47518490'::uuid,'b5b4a153-07f4-5744-8b18-a48deb76e309'::uuid,5,'Reissue designations (City Mayor). Reissue EOC, CDRRMC and focal designations as needed; update MODE roles. Check: All designations current? Record: Issuances; MODE role changes. [When: Within 60 days, Escalate to: CDRRMO Head]',true,true,null,'STEP-RECORD'),
('15c47765-fe23-5ba6-a170-809f518bca79'::uuid,'1c90a287-658f-5e7a-9de5-0419872ebc26'::uuid,1,'Decide production hosting (City Mayor with City ICT office and DPO). Before operational use, decide City-owned, paid hosting with daily backups; record a new ADR; confirm the DPO''s assessment of the data location. Check: Decision made before operational use? Record: Decision record; new ADR. [When: Before go-live, Escalate to: City Mayor]',true,true,null,'STEP-RECORD'),
('6435a9a5-eb5c-5c8d-891d-5f5513157b34'::uuid,'1c90a287-658f-5e7a-9de5-0419872ebc26'::uuid,2,'Weekly backup (City ICT office). Check the daily backup; take a pg_dump; copy the evidence and Vault buckets; clear old error reports. Check: Backup present and readable? Record: SUS-F04 weekly entries. [When: Weekly, Escalate to: CDRRMO Head]',false,true,null,'SUS-F04'),
('f6ea3835-2fec-5ce7-95dc-40f59445d3a3'::uuid,'1c90a287-658f-5e7a-9de5-0419872ebc26'::uuid,3,'Restore test (City ICT office). Restore into the training project and run the checklist. Check: Restored data complete and the app works? Record: Restore test record. [When: Quarterly and before go-live, Escalate to: City Administrator]',false,true,null,'STEP-RECORD'),
('3c3d3db2-c4a7-5c96-ac7b-d058fb88a30f'::uuid,'1c90a287-658f-5e7a-9de5-0419872ebc26'::uuid,4,'Access review (City ICT office with CDRRMO Head). Review accounts and roles; remove leavers; confirm MFA for administrators. Check: Any account without a current owner or role? Record: Access review record. [When: Quarterly, Escalate to: CDRRMO Head]',true,true,null,'STEP-RECORD'),
('d4f30286-9b72-534c-9375-ad41014db307'::uuid,'1c90a287-658f-5e7a-9de5-0419872ebc26'::uuid,5,'Connectivity test (City ICT office with EOC). Switch to the second internet path; run the EOC in offline mode for a set period. Check: EOC kept working? Record: Test record. [When: Quarterly (connectivity); annually (offline), Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('e0fa4d70-1427-5cc8-b477-5a5c02fec345'::uuid,'1c90a287-658f-5e7a-9de5-0419872ebc26'::uuid,6,'Incident response (City ICT office with DPO). On a security incident, contain, assess and, where personal data are involved, follow Chapter 7 (SOP 7-09). Check: Personal data affected? Record: Incident record. [When: Immediately, Escalate to: City Mayor]',false,true,null,'STEP-RECORD'),
('b4288740-cdd2-5162-9561-f28ba338dc1b'::uuid,'8a479eb7-45d3-5b93-b7cd-3f9d3134fc78'::uuid,1,'Self-check both sites (EOC Manager). Complete the EOC Capability Assessment Checklist for the primary and alternate EOC: site, building, power, communications, supplies, security. Check: Any critical item missing? Record: SUS-F05 self-check. [When: Before the season, Escalate to: CDRRMO Head] Note: Alternate EOC items apply only where the City has designated an alternate EOC (IAT B2.7 is N/A otherwise).',false,true,null,'SUS-F05'),
('4a6f5d55-b6c4-5a72-9e84-bc155c536e1f'::uuid,'8a479eb7-45d3-5b93-b7cd-3f9d3134fc78'::uuid,2,'Relocation drill (EOC Manager). Relocate a working EOC cell to the alternate site with the go-kit; run a SitRep cycle from there. Check: Operational within the target time set in Chapter 2? Record: Drill record. [When: Annually, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('f8cd2fc0-473b-553c-8903-ae623821da8f'::uuid,'8a479eb7-45d3-5b93-b7cd-3f9d3134fc78'::uuid,3,'PSCP exercise (CDRRMO Head with PSCP team). Exercise the CDRRMO''s essential functions under a loss scenario (site, power, staff). Check: Essential functions continued? Record: Exercise record. [When: Annually, Escalate to: City Administrator]',true,true,null,'STEP-RECORD'),
('66453d00-2942-55e5-a570-507646b33ae0'::uuid,'8a479eb7-45d3-5b93-b7cd-3f9d3134fc78'::uuid,4,'3a. Maintenance check (EOC Logistics). Confirm the preventive maintenance schedule for EOC equipment was followed. Check: Overdue maintenance? Record: Maintenance status. [When: Annually, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('b5964207-4066-518b-b6c6-57b86f3c3fb4'::uuid,'8a479eb7-45d3-5b93-b7cd-3f9d3134fc78'::uuid,5,'Follow up (M&E unit). Enter gaps in the CAPA register; report to the sustainability review. Check: Each gap owned? Record: ME-F05 entries. [When: Within 15 days, Escalate to: CDRRMC]',false,true,null,'STEP-RECORD'),
('05561dd6-4ac7-560b-9ad1-61faaccec5cb'::uuid,'4697fbd7-fe28-50d7-879a-2614259ea149'::uuid,1,'Obtain the current rules (Research and Planning). Obtain the current Gawad KALASAG guidelines and assessment tool from OCD VIII and the SGLG criteria from the DILG City Office. Check: Current year''s version? Record: Rules on file. [When: On the call, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('e2ceaf85-c9f9-5ad4-90f0-cc12bfe3a2dc'::uuid,'4697fbd7-fe28-50d7-879a-2614259ea149'::uuid,2,'Check minimum requirements (Research and Planning). Check the six Gawad KALASAG minimum requirements (Table 10.5) and the SGLG core requirements. Check: Any minimum not met? Fix before submission or report to the Mayor. Record: Minimum-requirement check. [When: On the call, Escalate to: City Mayor]',false,true,null,'STEP-RECORD'),
('d03e76aa-4226-5294-a0e9-efe3ff212d4c'::uuid,'4697fbd7-fe28-50d7-879a-2614259ea149'::uuid,3,'Self-assess (Research and Planning). Complete the self-assessment honestly with the prescribed tool; use the MODE self-check only as a guide. Check: Every rating backed by a document in use? Record: Self-assessment; SUS-F06. [When: Per OCD VIII timeline, Escalate to: CDRRMO Head]',false,true,null,'SUS-F06'),
('8dfe7410-c821-5aa1-a26d-5cfab47036e5'::uuid,'4697fbd7-fe28-50d7-879a-2614259ea149'::uuid,4,'Submit (CDRRMO Head; City Mayor). Compile means of verification; the Mayor signs; submit to OCD VIII and DILG as required. Check: Complete and on time? Record: Submission; receipt. [When: By the deadline, Escalate to: City Mayor]',true,true,null,'STEP-RECORD'),
('0b9cc202-c77f-55a6-b6d6-0d781f0fbdcf'::uuid,'4697fbd7-fe28-50d7-879a-2614259ea149'::uuid,5,'Follow up (Research and Planning). On results, enter every gap and assessor comment in the CAPA register; report to the CDRRMC. Check: All gaps entered? Record: ME-F05 entries; report. [When: Within 30 days of results, Escalate to: CDRRMC]',false,true,null,'STEP-RECORD'),
('2e6a9723-12f5-501f-b49a-af85ea0f92ae'::uuid,'96a287a8-95f8-5e9a-845b-b9fae43077a7'::uuid,1,'Propose (Proposer). State the problem, the idea, the measure of success, the time limit, the cost and any personal data involved. Check: Linked to a real gap? Record: SUS-F07 proposal. [When: Any time, Escalate to: CDRRMO Head]',false,true,null,'SUS-F07'),
('6664319e-c677-5fc0-86e3-6442648fdd86'::uuid,'96a287a8-95f8-5e9a-845b-b9fae43077a7'::uuid,2,'Approve the pilot (CDRRMO Head). Approve, refine or decline; name an owner. Check: Within authority and budget? Record: Decision. [When: Within 30 days, Escalate to: CDRRMC]',true,true,null,'STEP-RECORD'),
('8b41376f-0a54-518c-89d0-f753d22e569e'::uuid,'96a287a8-95f8-5e9a-845b-b9fae43077a7'::uuid,3,'Pilot (Pilot owner). Run the pilot within its limits; record results. Check: Within time and scope? Record: Pilot records. [When: As approved, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('e730c307-2ee2-5915-8009-3f59a9204286'::uuid,'96a287a8-95f8-5e9a-845b-b9fae43077a7'::uuid,4,'Evaluate (M&E unit). Evaluate against the success measure. Check: Did it work? Record: Evaluation. [When: At the time limit, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('223fcc30-d401-5244-8e82-1d7477b3a5cb'::uuid,'96a287a8-95f8-5e9a-845b-b9fae43077a7'::uuid,5,'Adopt, scale or drop (CDRRMO Head). Adopt into the Manual (SOP 7-08), scale, or drop; share the lesson. Check: Needs an issuance or budget? Refer to the CDRRMC. Record: Decision; Manual change; ME-F08 entry. [When: Within 30 days, Escalate to: CDRRMC]',true,true,null,'STEP-RECORD'),
('43a5595c-acd1-52a0-903b-9e0bcb73820e'::uuid,'1a8580ca-d39e-5129-9578-810919685f26'::uuid,1,'Inventory (CDRRMO Head with City ICT office). List what must be handed over: approved Manual and source files, Library versions, repository, hosting accounts and keys, runbooks, training materials, registers. Check: Complete? Record: Handover inventory. [When: Four weeks before, Escalate to: City Administrator]',true,true,null,'STEP-RECORD'),
('a8da5923-f67e-5adf-9749-46ef9d86724a'::uuid,'1a8580ca-d39e-5129-9578-810919685f26'::uuid,2,'Transfer (Developer; City ICT office). Transfer ownership and credentials; confirm the City holds every account and key. Check: City can sign in to every account without the developer? Record: Transfer record. [When: Before the end date, Escalate to: City Mayor]',false,true,null,'STEP-RECORD'),
('14856bb5-afab-5386-a02e-9905ea9cb590'::uuid,'1a8580ca-d39e-5129-9578-810919685f26'::uuid,3,'Train the custodians (Developer). Train the City custodian and a local IT contractor on runbooks, migrations and restore. Check: Custodians can run a restore alone? Record: Training record; restore by City staff. [When: Before the end date, Escalate to: CDRRMO Head]',false,true,null,'STEP-RECORD'),
('b69094e7-390b-5d33-98c2-dde3fd68da5c'::uuid,'1a8580ca-d39e-5129-9578-810919685f26'::uuid,4,'Remove developer access (City ICT office). Run the developer-access removal script; confirm in the handover record. Check: Access removed everywhere? Record: Access removal record. [When: On the end date, Escalate to: City Mayor]',false,true,null,'STEP-RECORD'),
('dbe5fca6-b6fa-5af8-99c6-6b810f023513'::uuid,'1a8580ca-d39e-5129-9578-810919685f26'::uuid,5,'Accept (City Mayor). Sign the handover record. Check: All items checked? Record: Signed handover record. [When: End of the engagement, Escalate to: —]',true,true,null,'STEP-RECORD')
